const updatePlayerFromEdit = `-- name: UpdatePlayerFromEdit :one
UPDATE players
SET full_name = $1, nickname = $2,
    avatar_ref = CASE WHEN $3::bool THEN $4::text ELSE avatar_ref END,
    avatar_previous_ref = CASE WHEN $3::bool THEN $5::text ELSE avatar_previous_ref END,
    -- mergeDetails: the playing style laid over the stored details (an object; anything else reads as empty), so the getting-to-know
    -- answers kept beside it survive.
    personal_details = CASE WHEN $6::bool THEN (CASE WHEN jsonb_typeof(personal_details) = 'object' THEN personal_details ELSE '{}'::jsonb END) || $7::jsonb ELSE personal_details END,
    details_version = CASE WHEN $6::bool THEN 1 ELSE details_version END,
    experience_months = CASE WHEN $8::bool THEN $9::int ELSE experience_months END,
    experience_recorded_at = CASE WHEN $8::bool THEN $10::timestamptz ELSE experience_recorded_at END,
    profile_visibility = CASE WHEN $11::bool THEN $12::profile_visibility ELSE profile_visibility END,
    hide_phone_from_clubs = CASE WHEN $13::bool THEN $14::bool ELSE hide_phone_from_clubs END,
    revision = revision + 1, updated_at = $15
WHERE id = $16
RETURNING revision
`

type UpdatePlayerFromEditParams struct {
	FullName             string
	Nickname             pgtype.Text
	SetAvatar            bool
	AvatarRef            pgtype.Text
	AvatarPreviousRef    pgtype.Text
	SetStyle             bool
	PersonalDetails      []byte
	SetExperience        bool
	ExperienceMonths     pgtype.Int4
	ExperienceRecordedAt pgtype.Timestamptz
	SetVisibility        bool
	Visibility           ProfileVisibility
	SetPhonePrivacy      bool
	HidePhone            bool
	Now                  pgtype.Timestamptz
	ID                   pgtype.UUID
}

// The profile columns of an Admin edit. Each group is written only when its flag is set (the spread of the TypeScript's
// update data); the name, the nickname and the revision always are.
func (q *Queries) UpdatePlayerFromEdit(ctx context.Context, arg UpdatePlayerFromEditParams) (int64, error) {
	row := q.db.QueryRow(ctx, updatePlayerFromEdit,
		arg.FullName,
		arg.Nickname,
		arg.SetAvatar,
		arg.AvatarRef,
		arg.AvatarPreviousRef,
		arg.SetStyle,
		arg.PersonalDetails,
		arg.SetExperience,
		arg.ExperienceMonths,
		arg.ExperienceRecordedAt,
		arg.SetVisibility,
		arg.Visibility,
		arg.SetPhonePrivacy,
		arg.HidePhone,
		arg.Now,
		arg.ID,
	)
	var revision int64
	err := row.Scan(&revision)
	return revision, err
}
